  upload_status_finalizing: "Abschluss auf der PS5",
  upload_status_finalizing_hint: "Die PS5 schreibt den Dateiindex fest. Bei vielen Dateien kann das dauern — schließe die App nicht.",
  upload_file_list_windowed: "zeige {shown}",
  upload_file_list_windowed_hint: "Zeigt einen Ausschnitt rund um die aktuelle Datei; jeden Eintrag eines Ordners mit über 50.000 Dateien zu rendern würde die App einfrieren.",
  upload_eta_simplified: "Geschätzte Upload-Zeit: {eta}",
  upload_eta_default_qualifier: "Schätzung — erster Upload auf diese PS5",
