  upload_eta_resume_hint: "Bei Ordnern dieser Größe spart der Fortsetzen-Modus (bereits auf der PS5 vorhandene Dateien überspringen) bei wiederholten Uploads eine Stunde oder mehr. Du bekommst die Auswahl, wenn du auf Upload klickst.",
  activity_phase_finalizing_with_counter: "Wird auf der PS5 abgeschlossen — {done} / {total} Dateien",
