  upload_scanning_title: "Spielordner wird gescannt…",
  upload_scanning_hint: "Zählt Dateien und erstellt den Upload-Plan. Große Ordner (100.000+ Dateien) brauchen etwa 30 Sekunden. Die Upload-Schaltflächen werden danach aktiv.",
  upload_scanning_archive_title: "Archiv wird gescannt…",
