  upload_scanning_archive_hint: "Liest das zentrale Verzeichnis der .zip und wertet eingebettete Spiel-Metadaten aus. Die Upload-Schaltflächen werden aktiv, sobald das fertig ist.",
  upload_disabled_scanning: "Spielordner wird gescannt — warte, bis der Scan fertig ist, dann wird diese Schaltfläche aktiv.",
