err_fs_read_path_not_allowed: "Diese Datei liegt in einer schreibgeschützten Systempartition, die normalerweise gesperrt ist. Aktiviere Einstellungen → „Herunterladen von Systemdateien erlauben“, um aus /system, /system_data und anderen geschützten Pfaden zu lesen. Das betrifft nur Downloads — Löschen, Verschieben und Schreiben sind dort nie erlaubt.",
err_rar_open_failed: "Dieses RAR-Archiv konnte nicht gelesen werden. Bei einem mehrteiligen Satz wähle den ERSTEN Teil (…part1.rar / …part01.rar / ….rar) und stelle sicher, dass alle Teile im selben Ordner liegen. Falls es passwortgeschützt ist, gib das Passwort ein.",
