fs_install_confirm_body_usb: "Dies legt das Paket im internen Speicher ab (die Konsole kann nicht direkt von USB installieren), installiert es und entfernt die abgelegte Kopie danach wieder. Das Original auf deinem Laufwerk bleibt unangetastet.",
