cheats_your_games_hint: "Klicken Sie auf ein Spiel, um Cheats dafür zu finden, oder suchen Sie unten.",
err_rar_missing_volume: "Dieses mehrteilige RAR-Archiv ist unvollständig – {file} fehlt im Ordner. Laden oder kopieren Sie diesen Teil hinein und versuchen Sie es erneut.",
game_activity_reset: "Spielzeit zurücksetzen",
game_activity_reset_confirm: "Zurücksetzen",
game_activity_reset_explain: "Dies löscht dauerhaft die Spielzeit, die ps5upload auf dieser Konsole aufgezeichnet hat. Der Vorgang kann nicht rückgängig gemacht werden, und vergangene Sitzungen lassen sich nicht wiederherstellen. Die Aufzeichnungen Ihrer Konsole sind nicht betroffen – dies löscht nur, was dieser Bildschirm anzeigt.",
