imgbrowse_title: "In ein Abbild hineinsehen",
imgbrowse_explain: "Durchsuchen Sie jedes Spielabbild oder Paket, das ps5upload liest (.exfat, .ffpkg, .ffpfs, .ffpfsc oder ein mit dem Debug-Schlüssel erstelltes .pkg), auf jedem Computer, ohne es einzubinden. Speichern Sie eine Datei oder einen Ordner auf dem Computer, oder ändern Sie Dateien und schreiben Sie eine bearbeitete Kopie: Das geöffnete Abbild wird nie verändert.",
