imgbrowse_change_delete: "{path} löschen",
imgbrowse_change_put: "{from} nach {path} legen",
imgbrowse_undo: "Rückgängig",
imgbrowse_copy_explain: "Die Kopie ist ein komplett neues Abbild derselben Art, das neben dem Original mit -edited im Namen geschrieben, danach zurückgelesen und geprüft wird. Das dauert etwa so lange wie das Konvertieren des Spiels. Das Original wird nicht verändert.",
imgbrowse_write_copy: "Bearbeitete Kopie schreiben",
imgbrowse_discard: "Änderungen verwerfen",
imgbrowse_writing_copy: "Bearbeitete Kopie von {name} wird geschrieben",
imgbrowse_copy_done: "Bearbeitete Kopie geschrieben und geprüft",
imgbrowse_open_copy: "In die Kopie hineinsehen",
localimage_explain: "Das Abbild wird als normales Laufwerk auf diesem Computer geöffnet, sodass Sie Dateien darin hinzufügen, ersetzen und löschen können – zum Beispiel Patchdateien – mit dem Finder oder Explorer, genau wie bei einem USB-Stick. Änderungen werden direkt in die Abbilddatei geschrieben. ps5upload schreibt nie selbst in das Abbild; das übernimmt Ihr Betriebssystem. Werfen Sie es hier aus, wenn Sie fertig sind.",
localimage_filter: "Datenträgerabbilder",
localimage_none_hint: "Wählen Sie eine .exfat- oder .img-Datei, um sie als Laufwerk zu öffnen.",
localimage_not_mounted: "angehängt, aber es konnte nichts davon eingebunden werden",
localimage_open_failed: "Das Abbild ist unter {path} eingebunden, aber dieser Computer wollte es nicht öffnen. Öffnen Sie den Ordner selbst.",
