"pkg.reason.stream_unreachable": "Die PS5 hat diesen Computer nie erreicht, um das Paket abzurufen. Lass ps5upload durch die Firewall dieses Computers (unter Windows für private und öffentliche Netzwerke), halte Computer und PS5 im selben Netzwerk ohne VPN und stelle den Proxy-Server der PS5 auf „Nicht verwenden“. Hochladen & installieren funktioniert ohne diese Verbindung.",
"pkg.reason.stream_proxy": "Die Proxy-Einstellung der PS5 hat den Stream blockiert. Stelle in den erweiterten Netzwerkeinstellungen der PS5 den Proxy-Server auf „Nicht verwenden“ oder nutze Hochladen & installieren – das liest das Paket aus dem lokalen Speicher der PS5.",
