"fpkg.error": "Umwandlungsfehler",
"fpkg.lowSpace": "Wenig freier Speicher: Das Umwandeln kann bis zu {need} auf dem Ausgabelaufwerk brauchen, frei sind {free}.",
"fpkg.about": "Wähle einen Spielordner oder ein .exfat- bzw. .ffpkg-Mount-Image. Der Konverter liest den Verzeichnisbaum, prüft, ob alles für ein startfähiges Paket vorhanden ist, und schreibt ein .pkg im Debug-Format in den Ausgabeordner.",
"fpkg.aboutWhere": "Die Umwandlung läuft auf dem Rechner, auf dem die Engine läuft – diesem Computer, einem Docker-Host oder einem Android-Gerät –, nicht auf der Konsole. Nichts erreicht die Konsole, bis du das Paket installierst – per Stream von diesem Computer oder zuerst auf die PS5 hochgeladen.",
"fpkg.aboutSource": "Die Quelle muss ein bereits entschlüsselter Spielbaum sein. Eine Retail-Installation lässt sich hier nicht entpacken, und die Prüfung unten sagt es, wenn du so etwas gewählt hast.",
"fpkg.aboutChecks": "Was die Prüfung sucht",
"fpkg.checkEboot": "Eine eboot.bin im Wurzelverzeichnis des Baums – das Titelmodul. Es muss ein rohes ELF oder ein verpacktes SELF sein; ein Retail-signiertes Modul lässt sich nicht neu verpacken.",
"fpkg.checkParam": "sce_sys/param.json und keine sce_sys/param.sfo – eine param.sfo schickt den Startpfad der Konsole auf die PS4-Route.",
"fpkg.checkIcons": "Eine 36-stellige Content-ID, beide Icons und das Rechtemodul sce_sys/about/right.sprx.",
"fpkg.checkDrm": "Dass der DRM-Wert des Pakets Standard ist. Ein kostenloser oder upgradefähiger Wert lässt die Konsole den Titel sperren; er wird nur im Paket umgeschrieben, deine eigene Datei wird nie verändert.",
"payloads_essentials_title": "Empfohlen zusammen mit ps5upload",
"payloads_essentials_body": "Wenn du eine Konsole zum ersten Mal einrichtest, decken diese drei das meiste ab, was ps5upload erwartet: kstuff-lite (Kernel-Patches, auf die die meiste Homebrew angewiesen ist), ShadowMount+ (Spiel-Images aus dem Speicher einhängen) und nanoDNS (hält die Konsole von Sonys Update-Pfad fern). Alles andere in dieser Liste ist optional.",
