"profile.accountId.confirm_replace": "Platz {slot} hat bereits die Konto-ID {old}.\n\nWenn du sie auf {next} änderst, werden unter {old} erstellte Spielstände nicht mehr als zu diesem Profil gehörend erkannt. Sie werden nicht gelöscht – mit {old} kommst du wieder an sie heran.\n\nNotiere sie dir, bevor du fortfährst. Konto-ID ändern?",
