"library_mount_modal_rw_title": "Lesen und Schreiben – du kannst dieses Image bearbeiten",
"library_mount_modal_rw_body": "So eingehängt kannst du Dateien ersetzen, DLC hinzufügen oder einen Backport-Patch anwenden – bearbeite den Mount im Datei-Browser. Änderungen werden direkt in die Image-Datei geschrieben: Eine fehlerhafte Änderung kann das Spiel unstartbar machen und lässt sich nicht rückgängig machen, kopiere das Image also vorher, wenn es wichtig ist. Die PS5 kann auch von sich aus Spielstände in ein eingehängtes Image schreiben.",
"fs_add_files": "Dateien hinzufügen",
