kept_clean_title: "Diese Dateien von der PS5 löschen?",
kept_clean_body: "Alles in {path} ({size}) wird gelöscht. Das sind Überbleibsel, die ps5upload neu anlegen kann; deine Paketbibliothek und Spielstand-Backups bleiben unberührt.",
library_move_retry: "Verschieben erneut versuchen",
volumes_pkg_copies_here: "Paketkopien liegen hier",
volumes_store_pkg_copies: "Paketkopien hier ablegen",
volumes_pkg_copies_hint: "Was diese Auswahl bewirkt: „Hochladen & installieren“ kopiert die .pkg-Datei zuerst auf die PS5 und installiert dann von dieser Kopie. Hier legst du nur fest, auf welchem Laufwerk diese Kopien liegen. Wo Spiele installiert werden, ändert sich nicht (das bestimmt die PS5 in ihren Speichereinstellungen), und „Streamen & installieren“ legt gar keine Kopie an. Ist das gewählte Laufwerk nicht angeschlossen, landen Kopien im internen Speicher.",
saves_auto_folder_label: "Backup-Ordner",
captures: "Screenshots & Clips",
captures_title: "Aufnahmen",
"arcpkg.choose": "Archiv wählen…",
"arcpkg.help": "Für eine .zip, .7z oder .rar, die eine oder mehrere .pkg-Dateien enthält, in beliebigen Ordnern. Nur die Pakete werden entpackt, direkt auf die PS5 (auf diesem Computer wird nichts entpackt), und dann nacheinander installiert: das Basisspiel vor seinem Update, danach DLC. Ein mehrteiliges RAR (.part1.rar, .part2.rar…) funktioniert: Wähle den ersten Teil und lass die übrigen daneben liegen. Braucht ein RAR ein Passwort, wird danach gefragt; passwortgeschützte ZIP- und 7z-Dateien werden nicht unterstützt.",
"arcpkg.keepsRunning": "Das läuft weiter, wenn du einen anderen Bildschirm öffnest; es erscheint auch unter Aufgaben.",
"arcpkg.notArchive": "Diese Datei ist kein .zip-, .7z- oder .rar-Archiv.",
"arcpkg.pick": "Archiv wählen",
"arcpkg.title": "Pakete aus einem Archiv installieren",
"install.library.title": "Paketkopien auf der PS5",
"install.stream.file.help": "Wähle eine .pkg oder .fpkg oder ziehe eine irgendwo auf dieses Fenster. Lass die App geöffnet, bis die Installation fertig ist; der Fortschritt steht oben in der Warteschlange und unter Aufgaben.",
"install.stream.file.title": "Eine Paketdatei installieren",
"install.tab.stream.lead": "Die PS5 installiert direkt von diesem Computer oder von einem Link. Vorher wird keine Kopie auf die PS5 gelegt, sie braucht dort also keinen freien Platz, und es ist der zuverlässigste Weg.",
"install.tab.upload.lead": "Das Paket wird zuerst auf die PS5 kopiert und dann von dieser Kopie installiert. Nutze das, wenn die PS5 diesen Computer nicht erreicht (Streamen scheitert mit einem Netzwerkfehler) oder wenn du Pakete auf der PS5 behalten willst, um sie später ohne diesen Computer erneut zu installieren.",
"install.upload.file.browser": "Um von hier ein Paket auf die PS5 zu kopieren, braucht es die Desktop-App. Nutze in der Web-Oberfläche Streamen & installieren, oder installiere unten Pakete, die schon auf der PS5 liegen.",
"install.upload.file.help": "Wähle eine .pkg oder .fpkg. Die Kopie braucht auf der PS5 freien Platz für das ganze Paket und bleibt in der Liste unten, bis du sie entfernst.",
"install.upload.file.title": "Ein Paket auf die PS5 kopieren und installieren",
"linkcard.confirm.direct": "Die PS5 lädt das Paket selbst vom Link und installiert es. Dieser Computer wird nach dem Start nicht mehr gebraucht, und der Fortschritt steht auf der PS5 (Downloads), nicht hier. Kann die PS5 den Link nicht abrufen, streamt die App ihn stattdessen über diesen Computer. Eine Neuinstallation über ein installiertes Spiel kann es entfernen, falls Sonys Installer scheitert. Verwende nur Paket-Links, denen du vertraust und die du installieren darfst.",
"linkcard.confirm.download": "Dieser Computer speichert zuerst das ganze Paket auf seiner Festplatte und installiert es dann auf der PS5. Er muss wach bleiben, bis beides fertig ist, und braucht freien Platz für das Paket. Eine Neuinstallation über ein installiertes Spiel kann es entfernen, falls Sonys Installer scheitert. Verwende nur Paket-Links, denen du vertraust und die du installieren darfst.",
"linkcard.confirm.stream": "Dieser Computer lädt das Paket und reicht es direkt an die PS5 weiter; er muss also wach und verbunden bleiben, bis die Installation fertig ist. Auf der Festplatte wird nichts gespeichert. Eine Neuinstallation über ein installiertes Spiel kann es entfernen, falls Sonys Installer scheitert. Verwende nur Paket-Links, denen du vertraust und die du installieren darfst.",
"linkcard.confirm.title": "Von diesem Link installieren?",
"linkcard.fact.awake": "Computer wach halten",
"linkcard.fact.can_close": "Du kannst die App schließen",
"linkcard.fact.disk": "Braucht hier Speicherplatz",
"linkcard.fact.no_disk": "Kein Speicherplatz nötig",
"linkcard.fact.progress_here": "Fortschritt hier sichtbar",
"linkcard.fact.progress_ps5": "Fortschritt auf der PS5",
"linkcard.forget": "Aus der Liste entfernen",
"linkcard.help": "Füge einen direkten Download-Link zu einer .pkg ein. Vorher wird nichts auf die PS5 kopiert; ein 100-GB-Spiel braucht dort also keinen zusätzlichen Platz.",
"linkcard.how": "Wie soll es geholt werden?",
"linkcard.insecure": "Zertifikatsprüfung überspringen",
"linkcard.insecure_hint": "Für deinen eigenen Server oder eine Seite mit abgelaufenem Zertifikat. Es gilt hier, weil dieser Computer die Verbindung aufbaut.",
"linkcard.install": "Von Link installieren",
"linkcard.mode.direct": "Die PS5 lädt es herunter",
"linkcard.mode.direct_body": "Die PS5 ruft den Link selbst ab. Sie muss den Link erreichen können, und die Adresse muss kurz sein (eine lange kürzt die App und muss dann geöffnet bleiben).",
"linkcard.mode.download": "Erst hier herunterladen, dann installieren",
"linkcard.mode.download_body": "Dieser Computer speichert das ganze Paket und installiert es dann. Am langsamsten, aber ein Link, der abläuft oder mittendrin abbricht, kostet nur einen neuen Download.",
"linkcard.mode.stream": "Über diesen Computer streamen",
"linkcard.mode.stream_body": "Dieser Computer lädt über mehrere Verbindungen und reicht es direkt an die PS5 weiter. Meist am schnellsten, und es klappt auch, wenn nur dieser Computer den Link erreicht.",
"linkcard.name": "Bezeichnung (optional)",
"linkcard.name_hint": "Ein Name steht in der Warteschlange, unter Aufgaben und bei den letzten Links anstelle der Adresse, damit du Links unterscheiden und den richtigen wiederholen kannst.",
"linkcard.name_placeholder": "z. B. Astro Bot Update 1.05",
