"speedtest.help": "Sendet eine Testdatei an die PS5 und liest sie zurück, so wie eine echte Kopie läuft, und entfernt sie dann auf beiden Seiten. Gemessen wird dein Netzwerk zwischen diesem Computer und der PS5, nicht dein Internet.",
