"netdoctor.container.bridged.detail": "Die PS5 bekommt eine Container-Adresse, die sie nicht erreichen kann. Stream-Installationen schlagen daher fehl, und die Prüfungen der Verbindung dieses Computers sehen nur den Container.",
"netdoctor.container.bridged.fix": "Starte den Container mit Host-Netzwerk oder setze PS5UPLOAD_PKG_HOST_IP auf die LAN-Adresse des Hosts und veröffentliche Port 19113.",
"netdoctor.container.bridged.title": "Diese Engine läuft in einem Container in einem Bridge-Netzwerk",
"netdoctor.container.ok.detail": "Sie gibt der PS5 eine LAN-Adresse. Prüfungen der Verbindung dieses Computers sehen die Sicht des Containers.",
