"netdoctor.failed": "Die Prüfungen konnten nicht beendet werden: {error}",
"netdoctor.help": "Prüft die Verbindung zwischen diesem Computer und der PS5 und listet auf, was Übertragungen bremst, das Wichtigste zuerst. Es läuft auch ein Geschwindigkeitstest, außer einer lief in den letzten Minuten.",
"netdoctor.hint.dismiss": "Schließen",
