"netdoctor.host_link.virtual.detail": "Nicht geprüft: Die Verbindung ({iface}) ist ein virtueller Adapter, daher sind das Kabel oder das Wi-Fi dahinter nicht zu erkennen.",
"netdoctor.host_link.vpn.detail": "Dieser Computer leitet den Datenverkehr zur PS5 über {iface} um, ein VPN oder einen Tunnel. Das bremst jede Übertragung und kann manche ganz verhindern.",
"netdoctor.host_link.vpn.fix": "Schalte das VPN während der Übertragung aus oder lass lokalen Netzwerkverkehr daran vorbei (oft „Split-Tunneling“ oder „LAN zulassen“ genannt).",
"netdoctor.host_link.vpn.title": "Der Datenverkehr zur PS5 läuft über ein VPN",
