"netdoctor.limit.at_link.detail": "Der Geschwindigkeitstest maß {up} zur PS5 und {down} zurück, nahe an den {ceiling}, die diese Verbindung schafft. Die Verbindung selbst ist die Grenze.",
"netdoctor.limit.at_link.title": "Übertragungen laufen so schnell, wie diese Verbindung erlaubt",
"netdoctor.limit.below_link.detail": "Der Geschwindigkeitstest maß {up} zur PS5 und {down} zurück, deutlich unter den {ceiling}, die diese Verbindung liefern sollte.",
"netdoctor.limit.below_link.fix": "Etwas anderes bremst das Netzwerk: ein anderes Gerät, ein ausgelasteter Switch oder eine Router-Einstellung. Starte Router oder Switch neu und probiere ein anderes Kabel oder einen anderen Anschluss.",
"netdoctor.limit.below_link.title": "Das Netzwerk ist langsamer als es sein sollte",
"netdoctor.limit.busy.detail": "Nicht ausgeführt: Andere Übertragungen laufen, und ein Geschwindigkeitstest würde nur mit ihnen konkurrieren.",
"netdoctor.limit.drive.detail": "Das Zurücklesen von der PS5 lief mit {down}, das Senden dorthin aber nur mit {up}. Das Netzwerk ist in Ordnung; die PS5 hat die Daten nur langsam aufgenommen.",
"netdoctor.limit.drive.fix": "Schaffe etwas Platz auf dem Laufwerk der PS5. Nutze für Uploads auf ein externes Laufwerk ein schnelleres Laufwerk und den schnellsten USB-Anschluss der PS5.",
"netdoctor.limit.drive.title": "Das Schreiben auf der PS5 ist die langsame Seite",
"netdoctor.limit.failed.detail": "Der Geschwindigkeitstest wurde nicht beendet: {error}",
"netdoctor.limit.measured.detail": "{up} zur PS5 und {down} zurück gemessen. Nicht mit dem Möglichen verglichen, weil die Verbindungsart einer Seite unbekannt ist.",
"netdoctor.limit.near_link.detail": "Der Geschwindigkeitstest maß {up} zur PS5 und {down} zurück; diese Verbindung schafft etwa {ceiling}.",
"netdoctor.limit.near_link.title": "Übertragungen laufen etwas unter dem Besten dieser Verbindung",
