"netdoctor.link_speed.hop.fix": "Prüfe das Kabel der PS5 und den Anschluss an Router oder Switch: Nimm Cat5e oder besser und einen Gigabit-Anschluss.",
"netdoctor.link_speed.hop.title": "Etwas auf dem Weg läuft mit 100 Mb/s",
