"netdoctor.link_speed.unknown.detail": "Nicht geprüft: Dieser Computer hat seine Kabelgeschwindigkeit nicht gemeldet.",
"netdoctor.load_latency.balloons.detail": "Die PS5 antwortet in {idle} ms, wenn das Netzwerk ruhig ist, aber in {loaded} ms, während eine Datei gesendet wird. Ein Router oder Wi-Fi, der zu viele Daten zurückhält, bremst jede Übertragung.",
"netdoctor.load_latency.balloons.fix": "Nutze ein Netzwerkkabel, geh näher an den Router oder aktiviere die Einstellung Smart Queue oder QoS deines Routers.",
