"netdoctor.mtu.mismatch.fix": "Nutze auf beiden 1500, die übliche Größe: Schalte Jumbo Frames an diesem Computer aus und stelle die MTU der PS5 in den erweiterten Einstellungen ihrer Internetverbindung auf automatisch.",
