"collection.trash_unavailable_v2": "Diese Engine hat keinen Papierkorb. Um hier Kopien zu löschen, schalte „Kopien endgültig löschen erlauben“ unter Sammlung → Ordner ein.",
"pkg.sony_80b21104": "Die PS5 hat dieses Paket nicht angenommen (0x80B21104). Wenn andere Pakete auf dieser Konsole installieren, liegt es an dieser Datei: meist ein neues Spiel, dessen Paket mit Werkzeugen erstellt wurde, die neuer sind, als die Firmware dieser Konsole versteht, oder ein Paket, das kein fake-signiertes (FPKG) Build ist. Nimm ein Paket für deine Firmware (ein Backport) oder installiere das Spiel ohne den Installer: kopiere seinen Spielordner oder ein Spiel-Image (.exfat oder .ffpfsc) für ShadowMount+ mit Hochladen.",
