pairing_closed_body_v3: "Diese PS5 fragt nach, bevor sich ein neues Gerät verbindet. Öffne auf einem bereits verbundenen Gerät (etwa der Desktop-App) Verbindung und drücke Anderes Gerät koppeln lassen, dann versuche es hier erneut. Oder drücke Helfer erneut senden, das lässt diese App von selbst herein. Der Besitzer kann die Nachfrage unter Geräte abschalten.",
