mesh_downgrade_title: "Helfer v{running} durch die ältere v{ours} dieser App ersetzen?",
mesh_downgrade_body: "Ein anderes Gerät hat einen neueren Helfer gesendet. Ihn zu ersetzen nimmt seine neueren Funktionen und Korrekturen jedem Gerät weg, das diese Konsole nutzt. Diese App zu aktualisieren ist die bessere Lösung.",
mesh_downgrade_confirm: "Durch älteren Helfer ersetzen",
mesh_busy_title: "Andere Geräte nutzen diese Konsole",
mesh_busy_body: "{work}. Den Helfer zu senden startet ihn neu: Ihre Arbeit stoppt, und Uploads machen dort weiter, wo sie aufgehört haben, sobald er wieder läuft.",
mesh_busy_confirm: "Trotzdem senden",
