mesh_need_helper_body: "Die Liste liegt auf der Konsole, daher muss ihr Helfer laufen.",
mesh_old_helper_body: "Auf dieser Konsole läuft ein Helfer von vor 8.0.0. Sende den Helfer dieser App unter Verbindung, dann erscheint hier jedes Gerät, das diese Konsole nutzt.",
