"fpkg.image.lz4_install_runtime_body": "{reason}. Das Image erhält drakmors ampr_emu 0.4.2.1 als fakelib/libSceAmpr.sprx (einmalig vom GitHub-Release geladen und gegen eine bekannte Prüfsumme geprüft); die eigene Kopie des Spiels bleibt daneben als libSceAmpr.sprx.orig.",
"fpkg.image.lz4_no_ampr": "Dieses Spiel liest seine Dateien nicht über AMPR, also könnte nichts darin Asset-Packs bedienen. Komprimiere es stattdessen in eine .ffpfsc: das entpackt ShadowMount+ für jedes Spiel.",
"fpkg.image.verify_chunk": "Gegenprüfung, pro Lesevorgang",
"fpkg.image.verify_chunk_body": "Nach dem Schreiben wird das Abbild zurückgelesen und geprüft. 8 MiB war in der Messung am schnellsten; probiere einen anderen Wert, falls dein Laufwerk anders reagiert. Die Prüfung selbst ist bei jeder Größe dieselbe.",
