"fakegame.fw.body": "Es lässt sich installieren, aber PS5-Fake-Spielpakete können auf Firmware über {last} nicht gespielt werden. PS4-Pakete funktionieren, und PS5-Homebrew-Apps starten normal.",
"fakegame.fw.launch": "PS5-Fake-Spielpakete können auf Firmware über {last} nicht gespielt werden (diese Konsole hat {fw}). Wenn dieses Spiel aus einem Fake-Paket installiert wurde, startet es deshalb nicht. PS4-Pakete funktionieren.",
