first_run_helper_only_hint: "Lädst du kstuff schon selbst (ein Autoloader, etaHEN, elf-arsenal)? Sende nur ps5upload — kstuff ein zweites Mal zu laden, stapelt eine weitere Kopie. Bereits laufende Payloads werden in jedem Fall übersprungen.",
