install_hint_setup_exe: "Das Installationsprogramm wurde geöffnet: Folge den Anweisungen, es aktualisiert PS5Upload direkt.",
install_path_fallback_hint: "Ein letzter Ausweg für ein Paket, das bereits auf der PS5 liegt, wenn die PS5 es aus ihrem eigenen Speicher ablehnt und es auch nicht von diesem Computer abrufen kann. Wird nur für ein nicht installiertes Basisspiel verwendet und kann daher nichts entfernen. Unerprobt: Es hat auf Firmware 11.20 funktioniert und wird auf 13.60 abgelehnt. Wenn du es ausprobierst, melde bitte, ob es funktioniert hat.",
install_path_fallback_label: "Über den Dateipfad installieren, wenn die PS5 diesen Computer nicht erreicht",
"installed_fix_permissions": "Berechtigungen reparieren: den Ordner dieses Spiels für die PS5 lesbar und ausführbar machen (chmod 777)",
