"ps4move_account_hint": "Ein Spielstand folgt der Konto-ID: Die ID des PS4-Kontos muss die dieses Benutzers sein. Wenn nicht, setze sie unter Konten (das ändert, welche Spielstände dieser Benutzer öffnen kann), bevor du weitermachst.",
