"ps4move_mismatch": "Die IDs unterscheiden sich: Die Spielstände der PS4 würden sich für diesen Benutzer nicht öffnen. Gib diesem Benutzer zuerst unter Konten die ID des PS4-Kontos oder wähle einen anderen Benutzer.",
