"ps4move_confirm_body": "Der Spielstand jedes Spiels dieses PS5-Benutzers wird gesichert und dann durch den der PS4 ersetzt. Die Spiele müssen geschlossen sein. Einen PS5-Spielstand kannst du aus seinen Sicherungen zurückholen (markiert mit „Vor einem PS4-Spielstand“).",
