"collection.convert_hint_v2": "In der Werkstatt öffnen: ein installierbares Paket oder ein anderes Spiel-Image erstellen.",
"collection.shrink_hint_v2": "In der Werkstatt öffnen, eingestellt auf ein komprimiertes Spiel-Image (.ffpfsc). Wie viel Platz das spart, hängt vom Spiel ab.",
