"rp_err_no_decoder": "Dieses Gerät hat keinen H.264-Videodecoder, daher kann Remote Play das Bild nicht anzeigen.",
"rp_err_no_decoder_linux": "Unter Linux dekodiert das GStreamer deines Systems das Bild. Installiere dessen H.264-Decoder und starte die App neu. Arch, CachyOS, Manjaro: sudo pacman -S gst-libav. Debian, Ubuntu, Mint: sudo apt install gstreamer1.0-libav. Fedora: sudo dnf install gstreamer1-plugin-openh264. Oder spiele über die Web-Oberfläche in Chrome oder Chromium.",
