"saves_use_shared": "Geteilten Spielstand verwenden",
"saves_use_shared_confirm_body": "Die Dateien deines Spielstands werden durch die des geteilten ersetzt, und die PS5 behält ihn als deinen. Dein eigener Spielstand wird vorher gesichert (Speicherdaten-Sicherungen) und bei einem Fehler zurückgelegt. Schließe zuerst das Spiel.",
