"play_not_ready_body": "Ein paar Schritte, einmal pro Konsole: Die Checkliste erledigt, was sie kann, und hakt jeden Schritt ab, sobald er erledigt ist.",
"play_setup_account_body": "Spielen koppelt sich mit einer Konto-ID. Ein mit dem PlayStation Network verknüpfter Benutzer hat schon eine; ein Offline-Benutzer braucht eine: lege sie unter Konten fest (jede ID geht; notiere sie, danach erstellte Spielstände hängen daran).",
"play_setup_all_done": "Spielen ist bereit",
"play_setup_connect_body": "Jailbreake die PS5 und lass die App ihren Helfer senden (das macht Verbindung). Alles unten wird über ihn von der Konsole gelesen.",
"play_setup_connect_title": "Mit deiner PS5 verbinden",
"play_setup_description": "Spielen streamt deine PS5 über Remote Play in diese App. Diese Schritte bringen eine Konsole einmal dorthin; jeder hakt sich selbst ab, sobald er erledigt ist.",
"play_setup_from_accounts": "Spielen einrichten? Spielen › Einrichten führt durch jeden Schritt und hakt jeden selbst ab.",
"play_setup_other_apps": "Lieber Sonys PS Remote Play-App oder chiaki-ng? Konten › Remote Play erzeugt die PIN, die sie verlangen.",
"play_setup_pair": "Koppeln",
"play_setup_pair_body": "Ein Klick registriert diese App bei der PS5 (wie das Koppeln der PS Remote Play-App) und speichert ihre Schlüssel auf diesem Gerät. Streamen, Wecken und Anmelden nutzen sie; nach einem Zurücksetzen der Konsole oder einem Benutzerwechsel neu koppeln.",
"play_setup_play_body": "Öffne Spielen und drücke Start: Die App weckt die Konsole, meldet an und streamt. Dieser Schritt hakt sich mit dem ersten Bild ab.",
