"play_setup_rest_undo": "Noch nicht erledigt",
"play_setup_short": "Einrichten",
"play_setup_signin_body": "Die PS5 lässt nur ein angemeldetes Konto streamen. Führe hier die Offline-Anmeldung aus (nichts geht an Sony), starte dann die PS5 neu und sende den Helfer erneut: Dieser Schritt hakt sich selbst ab, sobald die Konsole zurück ist.",
