"rp_fit_short_fill": "Füllen",
"rp_set_next_start_v2": "Auflösung und Bildrate gelten beim nächsten Start. Die Bildgröße gilt sofort; sie wirkt im Vollbild, wo die Form des Bildschirms von der des Bildes abweichen kann.",
"rp_browser_best": "Spielen läuft am besten in Chrome oder Edge",
"rp_browser_firefox": "In Firefox verlässt Esc immer das Vollbild und kann dort nicht ○ des Controllers sein, und Bild-in-Bild gibt es nicht.",
"rp_browser_safari": "In Safari verlässt Esc immer das Vollbild und kann dort nicht ○ des Controllers sein, und Bild-in-Bild zeigt nur das Bild.",
"rp_browser_other": "Es ist für sie gemacht und mit ihnen getestet. Hier funktionieren Esc als ○ des Controllers im Vollbild und Bild-in-Bild eventuell nicht.",
"rp_browser_other_mobile": "Es ist für Chrome auf Android gemacht und damit getestet.",
