"rp_keep_10m": "10 Minuten",
"rp_keep_hint": "Andere Bildschirme lassen den Stream laufen; so lange wartet er, wenn ihn kein Fenster zeigt (geschlossen oder neu geladen), bevor er endet.",
"rp_game_mode_mac": "Während du spielst, bleiben Computer und Bildschirm wach. Vollbild schaltet außerdem den Spielmodus ein (macOS 14 und neuer).",
"rp_game_mode_ios": "Der Spielmodus schaltet sich ein, solange die App den Bildschirm füllt (iOS und iPadOS 18 und neuer).",
"rp_game_mode_windows": "Während du spielst, bleiben Computer und Bildschirm wach. Windows lässt eine App den Spielmodus nicht einschalten; siehe FAQ.",
"rp_game_mode_linux": "Während du spielst, bleiben Computer und Bildschirm wach, und GameMode (gamemoded) wird eingeschaltet, falls installiert.",
"rp_game_mode_android": "Während du spielst, bleibt der Bildschirm an, das Gerät hält wo möglich ein gleichmäßiges Tempo, und ein Fernseher an HDMI wird um seinen Spielmodus gebeten.",
"rp_set_controls": "Steuerung",
"rp_capture_pointer": "Klick ins Bild blendet den Zeiger aus",
"rp_capture_pointer_hint": "Esc zeigt ihn wieder.",
"rp_rumble": "Controller-Vibration",
"rp_dualsense": "DualSense-Effekte",
"rp_dualsense_hint": "Mit einem DualSense an diesem Computer: adaptive Trigger und, per USB angeschlossen, haptisches Feedback. Gilt ab dem nächsten Start.",
"rp_mic_setting": "Mikrofon (experimentell)",
"rp_mic_setting_hint": "Fügt eine Mikrofontaste für Sprachchat hinzu. Gilt ab dem nächsten Start.",
"rp_touch_controls": "Bildschirm-Controller",
"rp_touch_auto": "Bei Touchscreens",
"rp_touch_on": "Immer",
"rp_touch_off": "Nie",
"rp_controls_hint": "Ein Controller geht auch: anschließen oder mit diesem Gerät koppeln. Shift + Ziehen im Bild ist ein Finger auf dem Touchpad.",
"rp_hid_touchpad": "DualSense-Touchpad verwenden",
"rp_hid_touchpad_hint": "Der Browser fragt nach dem Controller: Wähle den DualSense.",
"rp_hid_touchpad_on": "Das DualSense-Touchpad wird in diesem Browser gelesen.",
"rp_settings": "Einstellungen",
"rp_running_elsewhere": "Spielen läuft auf {name}",
"rp_show_here": "Hier anzeigen",
"rp_running_elsewhere_body": "Er wurde in einem anderen Fenster oder vor dem Neuladen dieser Seite gestartet und läuft noch.",
"rpg_user_title": "Einen Benutzer an der PS5 anmelden",
"rpg_user_body": "Wähle an der Konsole den Benutzer, mit dem du spielst. Niemand muss am Bildschirm bleiben, aber der Benutzer muss angemeldet sein. Nimm einen Benutzer ohne Anmelde-Passcode: Ein Passcode verhindert die automatische Anmeldung, wenn die Konsole aufwacht.",
"rpg_account_title": "Diesem Benutzer eine Konto-ID geben",
"rpg_account_body": "Remote Play koppelt über eine Konto-ID. Ein mit dem PlayStation Network verknüpfter Benutzer hat bereits eine; ein Offline-Benutzer braucht eine, die oben unter Benutzer gesetzt wird (jede ID funktioniert; schreib sie auf, danach erstellte Spielstände sind an sie gebunden).",
"rpg_signin_title": "Das Konto beim PlayStation Network anmelden (offline)",
"rpg_signin_body": "Die PS5 lässt nur ein angemeldetes Konto Remote Play nutzen. Ist die Remote-Play-Einstellung der Konsole ausgegraut, führe unten die Offline-Anmeldung aus (nichts wird an Sony gesendet) und starte die PS5 dann neu. Das lässt sich rückgängig machen.",
"rpg_signin_fix": "Zur Anmeldung",
"rpg_service_title": "Remote Play einschalten",
"rpg_service_body": "Einstellungen › System › Remote Play › Remote Play aktivieren. Die App kann es für dich einschalten und ab Firmware 10.00 auch für diesen Benutzer erlauben. Meldet Start danach, dass Remote Play ausgeschaltet ist, schalte es in den Einstellungen der PS5 selbst ein: Es zählt der Schalter auf der Konsole.",
"rpg_rest_title": "Aufwecken der PS5 aus dem Ruhemodus erlauben",
"rpg_rest_body": "Einstellungen › System › Energiesparen › Im Ruhemodus verfügbare Funktionen: Schalte „Mit dem Internet verbunden bleiben“ und „Einschalten der PS5 über das Netzwerk aktivieren“ ein. Ohne sie lässt sich eine Konsole im Ruhemodus nicht aufwecken, und ihr Netzwerk schläft nach wenigen Sekunden ein. Nur die Konsole kann diese anzeigen.",
"rpg_pair_title": "Diese App mit der Konsole koppeln",
"rpg_pair_body": "Verbindung › Wecken & anmelden › Einrichten. Ein Klick registriert diese App bei der PS5 (wie das Koppeln der PS Remote Play-App) und speichert ihre Schlüssel auf diesem Computer. Streamen, Aufwecken und Anmelden nutzen sie alle; wiederhole es nach dem Zurücksetzen der Konsole oder einem Benutzerwechsel.",
"rpg_play_title": "Spielen",
"rpg_play_body": "Öffne Remote Play und drücke Start: Die App weckt die Konsole, falls sie ruht, meldet an und streamt. Spiele mit einem Controller an diesem Computer, der Tastatur oder per Touch. Um stattdessen Sonys PS Remote Play-App oder chiaki-ng zu nutzen, fordere unten eine PIN an und gib sie dort ein.",
"rpg_play_fix": "Remote Play öffnen",
"rpg_title": "Remote Play einrichten",
"rpg_progress": "{done} von {n} geprüften Schritten erledigt",
"rpg_on_console": "an der Konsole prüfen",
"rpg_trouble": "Wenn es immer noch nicht klappt",
"rpg_t_start_q": "Start ist auf dem Spielen-Bildschirm ausgegraut.",
"rpg_t_start_a": "Diese App ist noch nicht mit dieser Konsole gekoppelt: Mach Schritt 6 (Verbindung › Wecken & anmelden › Einrichten).",
"rpg_t_pair_q": "Beim Einrichten der Kopplung heißt es, es gebe keinen angemeldeten Benutzer mit aktiviertem Konto.",
"rpg_t_pair_a": "Schritte 1 und 2: Melde einen Benutzer an der PS5 an und gib ihm eine Konto-ID, dann versuche es erneut.",
"rpg_t_grey_q": "Die Remote-Play-Einstellung der PS5 selbst ist ausgegraut.",
"rpg_t_grey_a": "Das Konto ist nicht beim PlayStation Network angemeldet. Führe die Offline-Anmeldung aus (Schritt 3) und starte die PS5 neu.",
"rpg_t_wake_q": "Die Konsole wacht nicht auf oder wacht auf, bleibt aber in der Benutzerauswahl.",
"rpg_t_wake_a": "Prüfe Schritt 5 an der Konsole. Ein Benutzer mit Anmelde-Passcode verhindert die automatische Anmeldung. Wurde die Konsole zurückgesetzt oder der Benutzer gewechselt, richte die Kopplung erneut ein (Schritt 6).",
"rpg_t_black_q": "Das Bild bleibt schwarz, ruckelt, oder der Ton knistert.",
"rpg_t_black_a": "Verbinde PS5 und diesen Computer per Kabel oder 5 GHz Wi-Fi und probiere 720p oder 30 fps in den Remote-Play-Einstellungen. Eine Firewall auf diesem Computer muss die App im lokalen Netzwerk zulassen (Remote Play nutzt die TCP- und UDP-Ports 9295–9304). Im Browser nimm einen aktuellen Chrome, Edge oder Safari: Das Bild braucht WebCodecs.",
"rpg_t_busy_q": "Es heißt, die PS5 beende noch die letzte Sitzung oder eine andere Konsole streame gerade.",
"rpg_t_busy_a": "Es streamt immer nur eine Konsole, und die PS5 braucht nach dem Ende einer Sitzung bis zu 30 Sekunden. Beende den anderen Stream, warte kurz und drücke dann erneut Start.",
"rpg_t_restrict_q": "Nach der Offline-Anmeldung verlangen Spiele, die Konsolenbeschränkungen zu deaktivieren.",
"rpg_t_restrict_a": "Nutze „Anmeldung rückgängig machen“ auf dieser Seite und starte neu, oder hebe die Beschränkung unter Einstellungen › Familie und Jugendschutzeinstellungen › PS5-Konsolenbeschränkungen auf (Passcode 0000, sofern nicht geändert).",
