"rp_other_device_playing_body": "Eine PS5 spielt Remote Play mit jeweils nur einem Gerät: Ein Start hier beendet es dort.",
"mesh_rp_started": "{name} hat auf dieser Konsole zu spielen begonnen",
"rp_keys_body3": "Ins Bild klicken, um mit der Tastatur zu spielen; Esc gibt den Zeiger zurück. Doppelklick für Vollbild; dort ist kurz Esc Kreis, und Esc gedrückt halten verlässt das Vollbild. Tasten, Ton und mehr unter Einstellungen.",
