"notif_app_hint": "Was ps5upload dir gemeldet hat: abgeschlossene oder fehlgeschlagene Uploads und Installationen, Updates. Die Glocke oben zeigt die neuesten. Beim Ansehen dieser Liste wird sie als gelesen markiert.",
"notif_ps5_hint": "Meldungen, die ps5upload auf dem Bildschirm deiner PS5 angezeigt hat (eine Remote-Play-PIN, ein eingeschalteter Cheat), alle 5 Sekunden von ihrem Helfer zurückgelesen. Nicht das eigene Benachrichtigungsfeld der PS5.",
